 49→// runTrailShow shows the trail for the current branch, or falls through to list.
 50→func runTrailShow(w io.Writer) error {
 51→	branch, err := GetCurrentBranch(context.Background())
 52→	if err != nil {
 53→		return runTrailListAll(w, "", false, false)
 54→	}
 55→
 56→	repo, err := strategy.OpenRepository(context.Background())
 57→	if err != nil {
 58→		return fmt.Errorf("failed to open repository: %w", err)
 59→	}
 60→
 61→	store := trail.NewStore(repo)
 62→	metadata, err := store.FindByBranch(branch)
 63→	if err != nil || metadata == nil {
 64→		return runTrailListAll(w, "", false, false)
 65→	}
 66→
 67→	printTrailDetails(w, metadata)
 68→	return nil
 69→}
