 71→func printTrailDetails(w io.Writer, m *trail.Metadata) {
 72→	fmt.Fprintf(w, "Trail: %s\n", m.Title)
 73→	fmt.Fprintf(w, "  ID:      %s\n", m.TrailID)
 74→	fmt.Fprintf(w, "  Branch:  %s\n", m.Branch)
 75→	fmt.Fprintf(w, "  Base:    %s\n", m.Base)
 76→	fmt.Fprintf(w, "  Status:  %s\n", m.Status)
 77→	fmt.Fprintf(w, "  Author:  %s\n", m.Author)
 78→	if m.Body != "" {
 79→		fmt.Fprintf(w, "  Body:    %s\n", m.Body)
 80→	}
 81→	if len(m.Labels) > 0 {
 82→		fmt.Fprintf(w, "  Labels:  %s\n", strings.Join(m.Labels, ", "))
 83→	}
 84→	if len(m.Assignees) > 0 {
 85→		fmt.Fprintf(w, "  Assignees: %s\n", strings.Join(m.Assignees, ", "))
 86→	}
 87→	fmt.Fprintf(w, "  Created: %s\n", m.CreatedAt.Format(time.RFC3339))
 88→	fmt.Fprintf(w, "  Updated: %s\n", m.UpdatedAt.Format(time.RFC3339))
 89→}
