253→+/**
254→+ * Add a DEPRECATED_MOVED_TO_DATABASE_STORAGE marker file to the root of the
255→+ * trails orphan branch, signalling that trail metadata for this repo has been
256→+ * migrated to the database.
257→+ */
258→+export async function addTrailsMigratedMarker(
259→+  repoFullName: string,
260→+  accessToken: string,
261→+): Promise<void> {
262→+  const [owner, repo] = repoFullName.split("/");
263→+  const headers: Record<string, string> = {
264→+    Accept: "application/vnd.github+json",
265→+    "User-Agent": "entire-api",
266→+    "X-GitHub-Api-Version": "2022-11-28",
267→+    Authorization: `Bearer ${accessToken}`,
268→+  };
269→+
270→+  // Get current ref SHA
271→+  const refResponse = await fetch(
272→+    `${GITHUB_API}/repos/${owner}/${repo}/git/refs/heads/${TRAILS_BRANCH}`,
273→+    { headers },
274→+  );
275→+  if (!refResponse.ok) {
276→+    throw new Error(`Failed to get trails branch ref: ${refResponse.status}`);
277→+  }
278→+  const refData = await refResponse.json<{ object: { sha: string } }>();
279→+  const baseCommitSha = refData.object.sha;
280→+
281→+  // Get base tree
282→+  const commitResponse = await fetch(
283→+    `${GITHUB_API}/repos/${owner}/${repo}/git/commits/${baseCommitSha}`,
284→+    { headers },
285→+  );
286→+  if (!commitResponse.ok) {
287→+    throw new Error(`Failed to get commit: ${commitResponse.status}`);
288→+  }
289→+  const commitData = await commitResponse.json<{ tree: { sha: string } }>();
290→+  const baseTreeSha = commitData.tree.sha;
291→+
292→+  // Create an empty blob
293→+  const blobResponse = await fetch(
294→+    `${GITHUB_API}/repos/${owner}/${repo}/git/blobs`,
295→+    {
296→+      method: "POST",
297→+      headers: { ...headers, "Content-Type": "application/json" },
298→+      body: JSON.stringify({ content: "", encoding: "utf-8" }),
299→+    },
300→+  );

300→+  );
301→+  if (!blobResponse.ok) {
302→+    throw new Error(`Failed to create blob: ${blobResponse.status}`);
303→+  }
304→+  const blobData = await blobResponse.json<{ sha: string }>();
305→+
306→+  // Create tree with marker file at root
307→+  const treeResponse = await fetch(
308→+    `${GITHUB_API}/repos/${owner}/${repo}/git/trees`,
309→+    {
310→+      method: "POST",
311→+      headers: { ...headers, "Content-Type": "application/json" },
312→+      body: JSON.stringify({
313→+        base_tree: baseTreeSha,
314→+        tree: [
315→+          {
316→+            path: "DEPRECATED_MOVED_TO_DATABASE_STORAGE",
317→+            mode: "100644",
318→+            type: "blob",
319→+            sha: blobData.sha,
320→+          },
321→+        ],
322→+      }),
323→+    },
324→+  );
325→+  if (!treeResponse.ok) {
326→+    throw new Error(`Failed to create tree: ${treeResponse.status}`);
327→+  }
328→+  const treeData = await treeResponse.json<{ sha: string }>();
329→+
330→+  // Create commit
331→+  const newCommitResponse = await fetch(
332→+    `${GITHUB_API}/repos/${owner}/${repo}/git/commits`,
333→+    {
334→+      method: "POST",
335→+      headers: { ...headers, "Content-Type": "application/json" },
336→+      body: JSON.stringify({
337→+        message: "chore: mark trails as migrated to database storage",
338→+        tree: treeData.sha,
339→+        parents: [baseCommitSha],
340→+      }),
341→+    },
342→+  );
343→+  if (!newCommitResponse.ok) {
344→+    throw new Error(`Failed to create commit: ${newCommitResponse.status}`);
345→+  }
346→+  const newCommitData = await newCommitResponse.json<{ sha: string }>();
347→+
348→+  // Update ref
349→+  const updateRefResponse = await fetch(
350→+    `${GITHUB_API}/repos/${owner}/${repo}/git/refs/heads/${TRAILS_BRANCH}`,
351→+    {
352→+      method: "PATCH",
353→+      headers: { ...headers, "Content-Type": "application/json" },
354→+      body: JSON.stringify({ sha: newCommitData.sha }),
355→+    },
356→+  );
357→+  if (!updateRefResponse.ok) {
358→+    throw new Error(`Failed to update ref: ${updateRefResponse.status}`);
359→+  }
360→+}
