608→+  const now = new Date();
609→+  const createdAt = toDate(row.created_at);
610→+  const updatedAt = toDate(row.updated_at);
611→+  const mergedAt = row.merged_at ? toDate(row.merged_at) : null;
612→+  const syncedAt = row.synced_at ? toDate(row.synced_at) : now;
613→+
614→+  await db
615→+    .insertInto("repo_trails")
616→+    .values({
617→+      id,
618→+      repo_id: row.repo_id,
619→+      trail_id: row.trail_id,
620→+      branch: row.branch,
621→+      base: row.base,
622→+      title: row.title,
623→+      body: row.body ?? null,
624→+      status: row.status ?? "draft",
625→+      author: row.author,
626→+      assignees: JSON.stringify(row.assignees ?? []),
627→+      labels: JSON.stringify(row.labels ?? []),
628→+      priority: row.priority ?? "none",
629→+      type: row.type ?? null,
630→+      reviewers: row.reviewers ? JSON.stringify(row.reviewers) : null,
631→+      merge_base_sha: row.merge_base_sha ?? null,
632→+      head_sha: row.head_sha ?? null,
633→+      discussion: row.discussion ? JSON.stringify(row.discussion) : JSON.stringify({ comments: [] }),
634→+      reviews: row.reviews ? JSON.stringify(row.reviews) : null,
635→+      comment_count: row.comment_count ?? 0,
636→+      unresolved_count: row.unresolved_count ?? 0,
637→+      created_at: createdAt,
638→+      updated_at: updatedAt,
639→+      merged_at: mergedAt,
640→+      synced_at: syncedAt,
641→+    })
642→+    .onDuplicateKeyUpdate({
