644→+      base: row.base,
645→+      title: row.title,
646→+      body: row.body ?? null,
647→+      status: row.status ?? "draft",
648→+      author: row.author,
649→+      assignees: JSON.stringify(row.assignees ?? []),
650→+      labels: JSON.stringify(row.labels ?? []),
651→+      priority: row.priority ?? "none",
652→+      type: row.type ?? null,
653→+      reviewers: row.reviewers ? JSON.stringify(row.reviewers) : null,
