 501→   501→+	token = strings.TrimSpace(token)
 502→   502→+	if token == "" {
 503→   503→+		return errors.New("refusing to save empty token")
 504→   504→+	}
 505→   505→+
 506→   506→+	if err := keyring.Set(s.service, baseURL, token); err != nil {
 507→   507→+		return fmt.Errorf("save token to keyring: %w", err)
 508→   508→+	}
 509→   509→+
 510→   510→+	return nil
 511→   511→+}
