 513→   513→+// GetToken retrieves a stored token for the given base URL.
 514→   514→+// Returns an empty string (and no error) if no token is stored.
 515→   515→+func (s *Store) GetToken(baseURL string) (string, error) {
 516→   516→+	token, err := keyring.Get(s.service, baseURL)
 517→   517→+	if errors.Is(err, keyring.ErrNotFound) {
 518→   518→+		return "", nil
 519→   519→+	}
 520→   520→+	if err != nil {
 521→   521→+		return "", fmt.Errorf("get token from keyring: %w", err)
 522→   522→+	}
 523→   523→+
 524→   524→+	return token, nil
 525→   525→+}
