 531→   531→+		return nil
 532→   532→+	}
 533→   533→+	if err != nil {
 534→   534→+		return fmt.Errorf("delete token from keyring: %w", err)
 535→   535→+	}
 536→   536→+
 537→   537→+	return nil
 538→   538→+}
