1090→  1090→+func waitForApproval(ctx context.Context, poller deviceAuthClient, deviceCode string, expiresIn, interval int) (string, error) {
1091→  1091→+	expiry := time.Duration(expiresIn) * time.Second
1092→  1092→+	if expiry <= 0 || expiry > maxExpiresIn {
1093→  1093→+		expiry = maxExpiresIn
1094→  1094→+	}
1095→  1095→+	deadline := time.Now().Add(expiry)
1096→  1096→+	pollInterval := time.Duration(interval) * time.Second
1097→  1097→+	if pollInterval <= 0 {
1098→  1098→+		pollInterval = fallbackDeviceAuthPollInterval
1099→  1099→+	}
1100→  1100→+
1101→  1101→+	consecutiveErrors := 0
1102→  1102→+
1103→  1103→+	for {
1104→  1104→+		if time.Now().After(deadline) {
1105→  1105→+			return "", errors.New("device authorization expired")
1106→  1106→+		}
1107→  1107→+
1108→  1108→+		result, err := poller.PollDeviceAuth(ctx, deviceCode)
1109→  1109→+		if err != nil {
1110→  1110→+			consecutiveErrors++
1111→  1111→+			if consecutiveErrors >= maxTransientErrors {
1112→  1112→+				return "", fmt.Errorf("poll approval status (after %d consecutive failures): %w", consecutiveErrors, err)
1113→  1113→+			}
1114→  1114→+			// Transient error — wait and retry.
1115→  1115→+			select {
1116→  1116→+			case <-ctx.Done():
1117→  1117→+				return "", fmt.Errorf("wait for approval: %w", ctx.Err())
1118→  1118→+			case <-time.After(pollInterval):
1119→  1119→+			}
1120→  1120→+			continue
1121→  1121→+		}
1122→  1122→+		consecutiveErrors = 0
1123→  1123→+
1124→  1124→+		switch result.Error {
1125→  1125→+		case "":
1126→  1126→+			if result.AccessToken == "" {
1127→  1127→+				return "", errors.New("device authorization completed without a token")
1128→  1128→+			}
1129→  1129→+			return result.AccessToken, nil
1130→  1130→+		case "authorization_pending":
1131→  1131→+			// no-op, will sleep and retry below
1132→  1132→+		case "slow_down":
1133→  1133→+			pollInterval += slowDownBackoff
1134→  1134→+			if pollInterval > maxPollInterval {
1135→  1135→+				pollInterval = maxPollInterval
1136→  1136→+			}
1137→  1137→+		case "access_denied":
1138→  1138→+			return "", errors.New("device authorization denied")
1139→  1139→+		case "expired_token":
1140→  1140→+			return "", errors.New("device authorization expired")
1141→  1141→+		default:
1142→  1142→+			return "", fmt.Errorf("device authorization failed: %s", result.Error)
1143→  1143→+		}
1144→  1144→+
1145→  1145→+		select {
1146→  1146→+		case <-ctx.Done():
1147→  1147→+			return "", fmt.Errorf("wait for approval: %w", ctx.Err())
1148→  1148→+		case <-time.After(pollInterval):
1149→  1149→+		}
1150→  1150→+	}
1151→  1151→+}
