1153→  1153→+func openBrowser(ctx context.Context, browserURL string) error {
1154→  1154→+	u, err := url.Parse(browserURL)
1155→  1155→+	if err != nil || (u.Scheme != "https" && u.Scheme != "http") {
1156→  1156→+		return fmt.Errorf("refusing to open non-HTTP URL: %s", browserURL)
1157→  1157→+	}
1158→  1158→+
1159→  1159→+	var command string
1160→  1160→+	var args []string
1161→  1161→+
1162→  1162→+	switch runtime.GOOS {
