1164→  1164→+		command = "open"
1165→  1165→+		args = []string{browserURL}
1166→  1166→+	case "linux":
1167→  1167→+		command = "xdg-open"
1168→  1168→+		args = []string{browserURL}
1169→  1169→+	case "windows":
1170→  1170→+		command = "cmd"
1171→  1171→+		args = []string{"/c", "start", "", browserURL}
1172→  1172→+	default:
1173→  1173→+		return fmt.Errorf("unsupported platform %s", runtime.GOOS)
1174→  1174→+	}
1175→  1175→+
1176→  1176→+	cmd := exec.CommandContext(ctx, command, args...)
1177→  1177→+	if err := cmd.Start(); err != nil {
