1179→  1179→+	}
1180→  1180→+
1181→  1181→+	if err := cmd.Process.Release(); err != nil {
1182→  1182→+		return fmt.Errorf("release browser process: %w", err)
1183→  1183→+	}
1184→  1184→+
1185→  1185→+	return nil
1186→  1186→+}
