377→// navigateToTrailTree walks rootTree → shard → suffix and returns the trail's subtree.
378→func (s *Store) navigateToTrailTree(rootTreeHash plumbing.Hash, shard, suffix string) (*object.Tree, error) {
379→	rootTree, err := s.repo.TreeObject(rootTreeHash)
380→	if err != nil {
381→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
382→	}
383→
384→	shardEntry, err := rootTree.FindEntry(shard)
385→	if err != nil {
386→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
387→	}
388→
389→	shardTree, err := s.repo.TreeObject(shardEntry.Hash)
390→	if err != nil {
391→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
392→	}
393→
394→	trailEntry, err := shardTree.FindEntry(suffix)
395→	if err != nil {
396→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
397→	}
398→
399→	trailTree, err := s.repo.TreeObject(trailEntry.Hash)
400→	if err != nil {
401→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
402→	}
403→
404→	return trailTree, nil
405→}
406→
407→// readCheckpointsFromTrailTree reads checkpoints.json from a trail's subtree.
408→// Returns empty checkpoints if the file doesn't exist yet.
409→func (s *Store) readCheckpointsFromTrailTree(trailTree *object.Tree) (*Checkpoints, error) {
410→	cpEntry, err := trailTree.FindEntry(checkpointsFile)
411→	if err != nil {
412→		// No checkpoints file yet — return empty
413→		return &Checkpoints{Checkpoints: []CheckpointRef{}}, nil
414→	}
415→
416→	blob, err := s.repo.BlobObject(cpEntry.Hash)
417→	if err != nil {
418→		return nil, fmt.Errorf("failed to read checkpoints blob: %w", err)
419→	}
420→
421→	reader, err := blob.Reader()
422→	if err != nil {
423→		return nil, fmt.Errorf("failed to open checkpoints reader: %w", err)
424→	}
425→	defer reader.Close()
426→
427→	var checkpoints Checkpoints
428→	if err := json.NewDecoder(reader).Decode(&checkpoints); err != nil {
429→		return nil, fmt.Errorf("failed to decode checkpoints: %w", err)
430→	}
431→
432→	return &checkpoints, nil
433→}
434→
435→// commitAndUpdateRef creates a commit and updates the trails branch reference.
436→func (s *Store) commitAndUpdateRef(treeHash, parentHash plumbing.Hash, message string) error {
437→	authorName, authorEmail := checkpoint.GetGitAuthorFromRepo(s.repo)
438→	commitHash, err := checkpoint.CreateCommit(s.repo, treeHash, parentHash, message, authorName, authorEmail)
439→	if err != nil {
440→		return fmt.Errorf("failed to create commit: %w", err)
441→	}
442→
443→	newRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(paths.TrailsBranchName), commitHash)
444→	if err := s.repo.Storer.SetReference(newRef); err != nil {
445→		return fmt.Errorf("failed to update branch reference: %w", err)
446→	}
447→	return nil
448→}
449→
450→// getBranchRef returns the commit hash and root tree hash for the entire/trails/v1 branch HEAD
451→// without flattening the tree. Falls back to remote tracking branch if local is missing.
452→func (s *Store) getBranchRef() (commitHash, rootTreeHash plumbing.Hash, err error) {
453→	refName := plumbing.NewBranchReferenceName(paths.TrailsBranchName)
454→	ref, refErr := s.repo.Reference(refName, true)
455→	if refErr != nil {
456→		// Try remote tracking branch
457→		remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.TrailsBranchName)
458→		ref, refErr = s.repo.Reference(remoteRefName, true)
459→		if refErr != nil {
460→			return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("trails branch not found: %w", refErr)
461→		}
462→	}
463→
464→	commit, err := s.repo.CommitObject(ref.Hash())
465→	if err != nil {
466→		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get commit: %w", err)
467→	}
468→
469→	return ref.Hash(), commit.TreeHash, nil
470→}
471→
472→// getBranchTree returns the tree for the entire/trails/v1 branch HEAD.
473→func (s *Store) getBranchTree() (*object.Tree, error) {
474→	_, rootTreeHash, err := s.getBranchRef()
475→	if err != nil {
476→		return nil, err
477→	}
478→
479→	tree, err := s.repo.TreeObject(rootTreeHash)
480→	if err != nil {
481→		return nil, fmt.Errorf("failed to get tree: %w", err)
482→	}
483→
484→	return tree, nil
485→}
